// SigCell - microVM boot profile
var VM = { name: "SigCell", boot_ms: 3, memory_mb: 2, tech: "KVM + SigGuard" };
console.log("MicroVM: " + VM.name);
console.log("Boot: " + VM.boot_ms + " ms | Guest: " + VM.memory_mb + " MB | Tech: " + VM.tech);
console.log("Density on 64 GiB host: ~" + Math.floor(65536 / VM.memory_mb) + " instances");
